import{z as c,x as A,o as r,c as T,q as l,j as o,D as e,d as t,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"netfilter 与 conntrack","description":"","frontmatter":{"title":"netfilter 与 conntrack","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/netfilter-conntrack.md","filePath":"cs/netfilter-conntrack.md","lastUpdated":1791413859000}'),B={name:"cs/netfilter-conntrack.md"};function p(f,a,d,k,P,C){const E=A("Mermaid");return r(),T("div",null,[a[2]||(a[2]=l('<h1 id="netfilter-与-conntrack" tabindex="-1">netfilter 与 conntrack <a class="header-anchor" href="#netfilter-与-conntrack" aria-label="Permalink to &quot;netfilter 与 conntrack&quot;">​</a></h1><div class="epigraph"><p>netfilter 在包路径上设钩子；conntrack 把同一连接的各方向报文收成一项状态，NAT 与状态防火墙靠它。</p><footer>—— 据 Russel, Linux netfilter Hacking HOWTO；Linux nf_conntrack 文档</footer></div><p><a href="/cs/rx-path">RX</a>/<a href="/cs/tx-path-qdisc">TX</a> 已经点名钩子。<a href="/cs/kernel-tcp-impl">TCP</a> 有自己的状态，那是传输对端。防火墙需要 <strong>另一份</strong> 连接表。缺口是 netfilter 钩子位置与 conntrack 元组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PREROUTING、INPUT、FORWARD、OUTPUT、POSTROUTING 五类钩。iptables/nftables 在钩上匹配、丢、改、跳 NAT。无状态规则不能「只允许已建立」。conntrack：五元组 + 状态（NEW/ESTABLISHED/RELATED），ICMP 差错可 RELATED。缺口：表满则 drop（DoS）；NAT 改地址必须改校验与端口；与 <a href="/cs/socket-buffers">套接字</a> 查找用的是改后或改前地址，取决于钩点。本课不把 nft 语法写成手册。</p><p><span class="marginnote">术语翻译：五元组就是一条连接的「身份证号」——源 IP、源端口、协议、目的 IP、目的端口。conntrack 拿这个号记账：第一次见到的记 NEW，两个方向都见过面就升级 ESTABLISHED，超时或挥手后才销账。</span></p><p><span class="marginnote">数字实例：conntrack 表容量按内存推算，常见量级从 65536 条起。表一打满，新的 NEW 包直接被丢——外行人看到的现象是「服务器随机连不上，重启就好」，其实是被扫描或大流量 NAT 撑爆了表，而不是网卡或应用坏了。</span></p><p><span class="marginnote">nf_conn 可被 helper 解析 FTP 等。关闭 conntrack 对转发性能有好处，但 NAT 不能关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入包：PREROUTING 做 DNAT，路由，再 INPUT 或 FORWARD。出包：OUTPUT、POSTROUTING SNAT。对照 TCP 状态机：conntrack 不重传，只跟踪看见过的方向。对照 <a href="/cs/dm-crypt">dm-crypt</a>：一个改块，一个改包头。对照 LSM：netfilter 不是 inode 标签。</p>',10)),(r(),o(s,null,{default:e(()=>[i(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20PRE%5B%22PREROUTING%22%5D%0A%20%20PRE%20--%3E%20CT%5B%22conntrack%22%5D%0A%20%20CT%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%22%5D%0A%20%20RT%20--%3E%20INP%5B%22INPUT%20%E6%88%96%20FORWARD%22%5D%0A%20%20OUT%5B%22%E6%9C%AC%E6%9C%BA%E5%8F%91%E5%87%BA%22%5D%20--%3E%20POST%5B%22POSTROUTING%20NAT%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[t("netfilter 把「包策略」收成可编程钩，使 NAT 与防火墙成为 OS 功能而非旁路盒子。conntrack 是有状态的代价：内存与锁。不要写成安全产品对比文。与 "),n("a",{href:"/cs/namespaces"},"namespaces"),t("：每 netns 一份 conntrack，容器隔离靠后课 netns。")],-1)),a[5]||(a[5]=n("p",null,[n("span",{class:"marginnote"},"常见误区：初学者以为 conntrack 和 TCP 状态机一样懂重传、挥手、窗口。实际上它只记录「这个方向见没见过包」，比 TCP 的状态粗糙得多；它也不终结连接，只做记账、改写与放行——传输语义仍归 TCP 自己管。")],-1)),a[6]||(a[6]=n("p",null,"连接跟踪与应用层代理不同：它不终结 TCP，只改或放行。",-1)),(r(),o(s,null,{default:e(()=>[i(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22%E9%A6%96%E5%8C%85%EF%BC%9A%E8%A1%A8%E9%87%8C%E6%B2%A1%E6%9C%89%E5%85%83%E7%BB%84%22%5D%20--%3E%20NEW%5B%22%E5%BB%BA%E8%A1%A8%E9%A1%B9%EF%BC%9A%E7%8A%B6%E6%80%81%20NEW%22%5D%0A%20%20NEW%20--%3E%20POL%7B%22%E7%AD%96%E7%95%A5%E6%98%AF%E5%90%A6%E6%94%BE%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20POL%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%EF%BC%9A%E8%BF%9E%E4%B8%8D%E5%87%BA%E5%8E%BB%22%5D%0A%20%20POL%20--%3E%7C%22%E6%98%AF%22%7C%20EST%5B%22%E5%9B%9E%E5%8C%85%E5%88%B0%E8%BE%BE%EF%BC%9A%E5%8D%87%E7%BA%A7%20ESTABLISHED%22%5D%0A%20%20EST%20--%3E%20PASS%5B%22%E4%B9%8B%E5%90%8E%E5%8F%8C%E5%90%91%E5%8C%85%E6%9F%A5%E8%A1%A8%E5%8D%B3%E6%94%BE%E8%A1%8C%22%5D%0A%20%20TMO%5B%22%E8%B6%85%E6%97%B6%E6%97%A0%E6%B5%81%E9%87%8F%22%5D%20--%3E%20RM%5B%22%E8%A1%A8%E9%A1%B9%E5%9B%9E%E6%94%B6%EF%BC%8C%E4%BC%9A%E8%AF%9D%E7%AA%97%E5%8F%A3%E5%85%B3%E9%97%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>实现上：表满时 NEW 包被丢，表现为随机连不上。helper 解析载荷会放大 CPU，也是攻击面。flowtable 把已确认转发路径短路到更早的交换，绕过多次钩子。 读法上只引用<a href="/cs/kernel-tcp-impl">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>netfilter 与 conntrack</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 flowtable 硬件卸载的全部。不保证 conntrack 对所有隧道内层可见。下一课把整份栈复制一份：网络命名空间与 veth。</p><p>版本字段会变，课序钉的是机制对象「netfilter 与 conntrack」，不是某一主线内核的结构体名。 后课默认：钩子可过滤/NAT，conntrack 记连接。每容器一份协议栈如何用 veth 接起来，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>netfilter 钩在收发与转发路径上。</li><li>conntrack 用元组做有状态放行与 NAT。</li><li>netns 与 veth 是下一课。</li><li>出处：netfilter HOWTO；Linux nf_conntrack；Benvenuti。</li></ul>',8))])}const m=c(B,[["render",p]]);export{h as __pageData,m as default};
